type GitRunner = (_args: string[]) => { status: number | null; stdout?: string; stderr?: string };
type CommitResult = { repaired: boolean; blocker: string | null };

/** Shared dirty-worktree capture for handoff entry and automatic Git repair. */
export function commitDirtyFiles(rootDir: string, slug: string, git: GitRunner, log: (_message: string) => void, error: (_message: string) => void): CommitResult {
  const blocked = (blocker: string): CommitResult => { error(blocker); return { repaired: false, blocker }; };
  try {
    const status = git(['-C', rootDir, 'status', '--porcelain=v1', '-z', '--untracked-files=all']);
    if (status.status !== 0) { return blocked(failure('read worktree status', status)); }
    const records = (status.stdout || '').split('\0').filter(Boolean);
    for (let index = 0; index < records.length; index++) {
      const record = records[index];
      const state = record.slice(0, 2);
      const file = record.slice(3);
      if (['DD', 'AU', 'UD', 'UA', 'DU', 'AA', 'UU'].includes(state)) {
        return blocked(`Cannot auto-commit handoff changes: unresolved conflict in ${file}. Resolve conflicts in ${rootDir} and retry handoff.`);
      }
      if (!file || record[2] !== ' ') { return blocked('Cannot auto-commit handoff changes: invalid Git status output. Inspect git status and retry handoff.'); }
      if (/[RC]/.test(state)) {
        const source = records[++index];
        if (!source) { return blocked('Cannot auto-commit handoff changes: missing rename source in Git status. Inspect git status and retry handoff.'); }
      }
    }
    if (!records.length) { return { repaired: false, blocker: null }; }
    log('Auto-committing dirty files:');
    // Stage the checkout root: already staged deletions/renames may no longer
    // have their old path in the index, so restaging each status path can fail.
    const staged = git(['-C', rootDir, 'add', '--all', '--', '.']);
    if (staged.status !== 0) { return blocked(failure('stage mission changes', staged)); }
    const committed = git(['-C', rootDir, 'commit', '-m', `workflow(${slug}): auto-commit mission artifacts before handoff`]);
    if (committed.status !== 0) { return blocked(failure('commit mission changes', committed)); }
    log('Mission changes committed before handoff verification and rebase.');
    return { repaired: true, blocker: null };
  } catch (error) {
    return blocked(`Cannot auto-commit handoff changes: ${error instanceof Error ? error.message : String(error)}. Inspect git status in ${rootDir} and retry handoff.`);
  }
}

function failure(operation: string, result: { stdout?: string; stderr?: string }): string {
  const detail = [result.stderr, result.stdout].filter(Boolean).join('\n').trim();
  return `Cannot ${operation} before handoff${detail ? `: ${detail}` : ''}. Resolve the Git error and retry handoff.`;
}

