import type { WebMissionCard } from '../../src/interfaces/web/transport.js';
import { C, RADIUS, SPACE } from './palette.js';

/** Draw recorded and planned entries rather than guessing a plan from CP numbers. */
export function CheckpointPips({ card }: { card: WebMissionCard }) {
  const checkpoints = card.checkpointEvidence ?? [];
  if (checkpoints.length === 0) { return null; }
  return (
    <span aria-label="Checkpoint plan" style={{ display: 'flex', gap: SPACE.sm, flexWrap: 'wrap' }}>
      {checkpoints.map((checkpoint) => (
        <span
          key={checkpoint.name}
          aria-label={checkpoint.name}
          data-checkpoint-state={checkpoint.state}
          className={checkpoint.state === 'current' && card.currentCheckpoint === checkpoint.name && card.activity.work.kind === 'working' ? 'review-pip--running' : undefined}
          title={`${checkpoint.name}: ${checkpoint.description}${checkpoint.state ? ` (${checkpoint.state})` : ''}`}
          style={{ width: 16, height: 8, borderRadius: RADIUS.chip, background: (checkpoint.state === 'current' && card.currentCheckpoint === checkpoint.name) || checkpoint.state === 'completed' || checkpoint.goalCheck.length > 0 ? C.green : C.headEdge }}
        />
      ))}
    </span>
  );
}

